(()=>{
    const forms=[
      {id:'orders',title:"Doctor’s Orders and Progress Notes",code:'HF-HIM-015',image:'data:image/jpeg;base64,',y1:.165,y2:.202,x:[.252,.435,.609,.790],low:[.121,.294,.506,.619,.775]},
      {id:'medication',title:'Medication and Treatment Record',code:'HF-HIM-027',image:'data:image/jpeg;base64,',y1:.142,y2:.181,x:[.234,.420,.590,.783],low:[.100,.284,.506,.622,.775]},
      {id:'nurses',title:'Nurses Notes and Treatment Record',code:'HF-HIM-031',image:'data:image/jpeg;base64,',y1:.143,y2:.183,x:[.238,.420,.591,.784],low:[.102,.286,.507,.622,.778]},
      {id:'tpr',title:'TPR Record',code:'HF-HIM-040',image:'data:image/jpeg;base64,',y1:.166,y2:.202,x:[.253,.435,.606,.783],low:[.110,.290,.506,.620,.778]}
    ];
    // Each form contains its own original JPEG. No scan folder or external image host is required.
    // Blob URLs let the reference link open the image itself in a new tab.
    const referenceImageUrls = new Map();
    function referenceImageUrl(form){
      if(!referenceImageUrls.has(form.id)){
        const bytes=Uint8Array.from(atob(form.image.split(',')[1]),char=>char.charCodeAt(0));
        referenceImageUrls.set(form.id,URL.createObjectURL(new Blob([bytes],{type:'image/jpeg'})));
      }
      return referenceImageUrls.get(form.id);
    }
    const fields=[['last','Last name'],['first','First name'],['middle','Middle name'],['record','Health record number'],['age','Age'],['birth','Birthdate'],['male','Male checkbox'],['female','Female checkbox'],['ward','Ward']];
    const $=id=>document.getElementById(id), state={form:'orders',paper:'letter',selected:'last',shifts:{}};
    const sizes={letter:[215.9,279.4],a4:[210,297]};
    const patientIds=['last','first','middle','record','age','birth','ward'];
    function storeKey(){return 'heading-alignment-v1-'+state.form+'-'+state.paper}
    const alignmentDrafts = new Map(), dirtyAlignments = new Set(), alignmentErrors = new Map();
    function readSettings(){try{return JSON.parse(RISStore.getItem(storeKey()))||{}}catch{return {}}}
    function normalizeAlignment(s={}){return {x:Number(s.x)||0,y:Number(s.y)||0,font:Number(s.font)||10,fields:s.fields&&typeof s.fields==='object'?s.fields:{}}}
    function settings(){let key=storeKey();if(!alignmentDrafts.has(key))alignmentDrafts.set(key,normalizeAlignment(readSettings()));return JSON.parse(JSON.stringify(alignmentDrafts.get(key)))}
    // Editing updates the preview; Save Alignment explicitly persists this profile.
    function saveSettings(s){let key=storeKey();alignmentDrafts.set(key,JSON.parse(JSON.stringify(s)));alignmentErrors.delete(key);if(JSON.stringify(s)===JSON.stringify(normalizeAlignment(readSettings())))dirtyAlignments.delete(key);else dirtyAlignments.add(key);render()}
    function updateAlignmentStatus(){
      const key=storeKey(),form=forms.find(f=>f.id===state.form),paper=state.paper==='letter'?'US Letter':'A4';
      $('alignmentStatus').classList.toggle('is-unsaved',dirtyAlignments.has(key));
      $('alignmentStatus').textContent=alignmentErrors.get(key)||(dirtyAlignments.has(key)?'Unsaved alignment changes — click Save Alignment.':`Alignment ready for ${form.title} · ${paper}. Click Save Alignment to keep this position on this device and in your cloud account.`);
    }
    async function persistAlignment(){
      const key=storeKey(),form=forms.find(f=>f.id===state.form),paper=state.paper==='letter'?'US Letter':'A4',label=`${form.title} · ${paper}`;
      const saved=JSON.stringify(settings());
      const showing=()=>storeKey()===key&&!dirtyAlignments.has(key);
      // RISStore writes the profile to this browser immediately and to the cloud account right after.
      RISStore.setItem(key,saved);
      if(RISStore.getItem(key)!==saved){alignmentErrors.set(key,'Alignment could not be saved on this device. Browser storage is unavailable; the current position can still be printed.');updateAlignmentStatus();return}
      dirtyAlignments.delete(key);alignmentErrors.delete(key);render();
      if(showing())$('alignmentStatus').textContent=`Alignment saved on this device for ${label}. Saving to your cloud account…`;
      const synced=await RISStore.flush();
      if(showing())$('alignmentStatus').textContent=synced?`Alignment saved on this device and to your cloud account for ${label}.`:`Alignment saved on this device for ${label}. Cloud sync is pending and will retry automatically.`;
    }
    function loadSavedAlignment(){alignmentDrafts.set(storeKey(),normalizeAlignment(readSettings()));dirtyAlignments.delete(storeKey());alignmentErrors.delete(storeKey());syncControls();render();$('alignmentStatus').textContent='Saved alignment loaded for this form and paper size.';}
    window.addEventListener('ris-cloud-change',e=>{
      const key=e.detail&&e.detail.key;
      if(!key||!key.startsWith('heading-alignment-v1-')||dirtyAlignments.has(key))return;
      const open=key===storeKey(),before=open?JSON.stringify(settings()):'';
      alignmentDrafts.delete(key);
      if(!open)return;
      if(JSON.stringify(settings())===before)return;
      syncControls();render();$('alignmentStatus').textContent='Alignment updated from your cloud account.';
    });
    function patient(){let p=Object.fromEntries(patientIds.map(id=>[id,$(id).value.trim()]));p.sex=document.querySelector('input[name="sex"]:checked')?.value||'';return p}
    function dateText(v){if(!v)return '';const [y,m,d]=v.split('-');return `${m}/${d}/${y}`}
    function sample(){return {last:'TEST LAST',first:'TEST FIRST',middle:'TEST MIDDLE',record:'TEST-000000',age:'00',birth:'01/01/2000',sex:'male',ward:'TEST WARD'}}
    function values(){let p=patient();p.birth=dateText(p.birth);return $('testMode').checked?sample():p}
    function positions(form){return {last:[form.x[0],form.y1],first:[form.x[1],form.y1],middle:[form.x[2],form.y1],record:[form.x[3],form.y1],age:[form.low[0],form.y2],birth:[form.low[1],form.y2],male:[form.low[2],form.y2],female:[form.low[3],form.y2],ward:[form.low[4],form.y2]}}
    function coordinates(id,form,s){let [w,h]=sizes[state.paper],p=positions(form)[id],n=s.fields[id]||{};return {x:p[0]*w+s.x+(n.x||0),y:p[1]*h+s.y+(n.y||0)}}
    function render(){let form=forms.find(f=>f.id===state.form),[w,h]=sizes[state.paper],s=settings(),v=values();
      $('formOptions').innerHTML=forms.map(f=>`<button type="button" class="form-option ${f.id===state.form?'active':''}" data-form="${f.id}" aria-pressed="${f.id===state.form}"><span class="form-title">${f.title}</span><span class="form-code">${f.code}</span></button>`).join('');
      const imageUrl=referenceImageUrl(form);
      if($('formImage').src!==imageUrl)$('formImage').src=imageUrl;
      $('formImage').alt=`Reference scan: ${form.title} (${form.code})`;
      $('referenceImageLink').href=imageUrl;
      $('referenceImageLink').setAttribute('aria-label',`View reference image for ${form.title} (${form.code}) in a new tab`);
      $('previewName').textContent=form.title+' · '+form.code;$('previewPage').style.aspectRatio=`${w}/${h}`;
      $('pageRule').textContent=`@page{size:${state.paper==='letter'?'letter':'A4'} portrait;margin:0}`;
      let preview=$('previewFields');preview.replaceChildren();
      if(!printingBatch){$('printSheet').replaceChildren(createPrintPage(v));}
      for(let [id,title] of fields){let pos=coordinates(id,form,s),txt=id==='male'?(v.sex==='male'?'X':''):id==='female'?(v.sex==='female'?'X':''):v[id]||'';let display=txt||(!$('testMode').checked?title:'');
        let el=document.createElement('span');el.className='preview-field'+(id===state.selected?' selected':'')+(id==='male'||id==='female'?' sex':'');el.textContent=display;el.title=`Drag to position ${title}`;el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label',`Move ${title} on the form preview`);el.style.left=(pos.x/w*100)+'%';el.style.top=(pos.y/h*100)+'%';el.style.fontSize=`clamp(6px, ${s.font/10*1.45}vw, ${s.font*1.05}px)`;
        el.addEventListener('pointerdown',e=>{
          if(e.pointerType==='mouse'&&e.button!==0)return;
          e.preventDefault();state.selected=id;syncControls();preview.querySelectorAll('.preview-field').forEach(node=>node.classList.toggle('selected',node===el));
          let box=$('previewPage').getBoundingClientRect(),startX=e.clientX,startY=e.clientY,origin=coordinates(id,form,s),n=s.fields[id]||={};s.fields[id]=n;
          el.setPointerCapture(e.pointerId);el.style.cursor='grabbing';
          const move=event=>{if(event.pointerId!==e.pointerId)return;let x=Math.max(0,Math.min(w-5,origin.x+(event.clientX-startX)*w/box.width)),y=Math.max(0,Math.min(h-3,origin.y+(event.clientY-startY)*h/box.height));n.x=+(x-positions(form)[id][0]*w-s.x).toFixed(1);n.y=+(y-positions(form)[id][1]*h-s.y).toFixed(1);el.style.left=(x/w*100)+'%';el.style.top=(y/h*100)+'%';$('fieldX').value=n.x;$('fieldY').value=n.y};
          const finish=event=>{if(event.pointerId!==e.pointerId)return;el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',finish);el.removeEventListener('pointercancel',finish);el.style.cursor='';saveSettings(s)};
          el.addEventListener('pointermove',move);el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',finish);
        });
        el.addEventListener('keydown',e=>{let step=e.shiftKey?2:0.5,dx=e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0,dy=e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0;if(!dx&&!dy)return;e.preventDefault();state.selected=id;let next=settings();next.fields[id]||={};next.fields[id].x=+((next.fields[id].x||0)+dx).toFixed(1);next.fields[id].y=+((next.fields[id].y||0)+dy).toFixed(1);saveSettings(next);syncControls();let chosen=preview.querySelector('.preview-field.selected');chosen?.focus()});preview.append(el);

      }
      $('printButton').disabled=!$('testMode').checked&&!patientIds.some(id=>patient()[id])&&!patient().sex;
      $('status').textContent=$('testMode').checked?'Test mode: only TEST sample text will print.':'Review patient details before printing. Use Save patient information to keep changes in RIS.';
      updateAlignmentStatus();updateBatchButtons();
    }
    function syncControls(){let s=settings(),n=s.fields[state.selected]||{};$('shiftX').value=s.x;$('shiftY').value=s.y;$('fontSize').value=s.font;$('fieldX').value=n.x||0;$('fieldY').value=n.y||0;$('fieldPick').value=state.selected}
    $('formOptions').addEventListener('click',e=>{let b=e.target.closest('[data-form]');if(!b)return;state.form=b.dataset.form;syncControls();render()});
    $('fieldPick').innerHTML=fields.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');$('fieldPick').addEventListener('change',e=>{state.selected=e.target.value;syncControls();render()});
    $('paper').addEventListener('change',e=>{state.paper=e.target.value;syncControls();render()});
    for(let id of patientIds)$(id).addEventListener('input',render);document.querySelectorAll('input[name="sex"]').forEach(x=>x.addEventListener('change',render));$('testMode').addEventListener('change',render);
    for(let [id,key] of [['shiftX','x'],['shiftY','y'],['fontSize','font']])$(id).addEventListener('input',e=>{let s=settings();s[key]=Number(e.target.value)||0;saveSettings(s)});
    for(let [id,key] of [['fieldX','x'],['fieldY','y']])$(id).addEventListener('input',e=>{let s=settings();s.fields[state.selected]||={};s.fields[state.selected][key]=Number(e.target.value)||0;saveSettings(s)});
    $('resetAlignment').addEventListener('click',()=>{saveSettings(normalizeAlignment());syncControls();render()});
    $('saveAlignment').addEventListener('click',persistAlignment);
    $('loadAlignment').addEventListener('click',loadSavedAlignment);
    $('clearButton').addEventListener('click',()=>{loadRISPatient('');patientIds.forEach(id=>$(id).value='');document.querySelectorAll('input[name="sex"]').forEach(x=>x.checked=false);$('testMode').checked=false;render();$('last').focus()});
    $('printButton').addEventListener('click',()=>{printingBatch=false;render();window.print()});
    const ORDERS_KEY='lghMedicationOrdersV1', EXTRAS_KEY='lghKardexExtrasV1';
    let risOrders=[], selectedPatientId='', dirtyPatient=false, loadedSignature='';
    function readRIS(key,fallback){try{return JSON.parse(RISStore.getItem(key))||fallback}catch{return fallback}}
    function extrasFor(order){return {...(readRIS(EXTRAS_KEY,{})[order.id]||{}),...(order.kardexExtra||{})}}
    function normalizedSex(value){let v=String(value||'').trim().toLowerCase();return ['m','male'].includes(v)?'male':['f','female'].includes(v)?'female':''}
    function validDate(value){let v=String(value||'').trim(),m=v.match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m)return '';let d=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]));return d.getFullYear()===+m[1]&&d.getMonth()===+m[2]-1&&d.getDate()===+m[3]?v:''}
    function ageForDOB(value){if(!value)return '';let [y,m,d]=value.split('-').map(Number),today=new Date();let age=today.getFullYear()-y;if(today.getMonth()+1<m||(today.getMonth()+1===m&&today.getDate()<d))age--;return age>=0?String(age):''}
    function guessNames(order){
      const saved=order.patientHeading||{};
      if(saved.sourceName===String(order.patientName||''))return {last:saved.last||'',first:saved.first||'',middle:saved.middle||'',confirmed:true};
      let name=String(order.patientName||'').trim(),parts=name.split(',');
      // Comma notation identifies the surname; keep the given-name portion intact.
      return parts.length>=2?{last:parts[0].trim(),first:parts.slice(1).join(',').trim(),middle:'',confirmed:false}:{last:'',first:name,middle:'',confirmed:false};
    }
    function signature(order){let e=extrasFor(order);return JSON.stringify([order.patientName,order.hospitalNo,order.age,order.ward,order.roomNumber,order.patientHeading,e.sex,e.dob])}
    function filteredRIS(){let q=$('risPatientSearch').value.trim().toLowerCase();return risOrders.filter(o=>!q||[o.patientName,o.hospitalNo,o.roomNumber].some(v=>String(v||'').toLowerCase().includes(q)))}
    function updateRISPicker(){
      const pick=$('risPatientPick'),items=filteredRIS();pick.replaceChildren();
      const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=risOrders.length?'Select a patient': 'No saved patients — add a medication order first';pick.append(placeholder);
      const selected=risOrders.find(o=>o.id===selectedPatientId);
      const visible=selected&&!items.some(o=>o.id===selectedPatientId)?[selected,...items]:items;
      for(let o of visible){let option=document.createElement('option');option.value=o.id;option.textContent=`Room ${o.roomNumber||'—'} · ${o.patientName||'Unnamed patient'} · HN ${o.hospitalNo||'—'}`;pick.append(option)}
      pick.disabled=!risOrders.length;pick.value=selectedPatientId;
      let index=items.findIndex(o=>o.id===selectedPatientId);$('risPrev').disabled=index<=0;$('risNext').disabled=index<0||index>=items.length-1;
      $('risPatientPosition').textContent=index>=0?`${index+1} / ${items.length}`:`${items.length} patient(s)`;
      $('risSave').disabled=!selected;$('risReload').disabled=!selected;
      renderBatchPatients();
    }
    function loadRISPatient(id){
      let order=risOrders.find(o=>o.id===id);selectedPatientId=order?order.id:'';dirtyPatient=false;$('risSaveStatus').textContent='';
      patientIds.forEach(id=>$(id).value='');document.querySelectorAll('input[name="sex"]').forEach(x=>x.checked=false);$('testMode').checked=false;
      if(order){let e=extrasFor(order),names=guessNames(order);$('last').value=names.last;$('first').value=names.first;$('middle').value=names.middle;$('record').value=order.hospitalNo||'';$('ward').value=order.ward||'';$('birth').value=validDate(e.dob||order.birthdate||order.dob);$('age').value=ageForDOB($('birth').value)||String(order.age??'');let sex=normalizedSex(e.sex||order.sex);document.querySelectorAll('input[name="sex"]').forEach(x=>x.checked=x.value===sex);loadedSignature=signature(order);$('risPatientSummary').textContent=`${order.patientName||'Unnamed patient'} · Room ${order.roomNumber||'—'} · HN ${order.hospitalNo||'—'}`;$('risNameWarning').textContent=names.confirmed?'Saved name fields loaded.': 'Confirm last, first and middle names before printing. Older RIS records contain a single full-name field; no middle name is guessed.';}
      else{$('risPatientSummary').textContent='Select a saved patient to fill this heading, or enter details for a one-time print.';$('risNameWarning').textContent='';loadedSignature='';}
      updateRISPicker();render();
    }
    function allowPatientSwitch(){return !dirtyPatient||confirm('Discard unsaved heading edits and switch patients?')}
    function refreshRIS(){if(printingBatch)return;risOrders=RISPatientOrder.sortByRoom(readRIS(ORDERS_KEY,[]));if(selectedPatientId&&!risOrders.some(o=>o.id===selectedPatientId)){loadRISPatient('');$('risSaveStatus').textContent='This patient is no longer in RIS. Select another patient.';}else{updateRISPicker();if(selectedPatientId&&!dirtyPatient)loadRISPatient(selectedPatientId);}}
    async function saveRISPatient(){
      const p=patient();if(!selectedPatientId)return;
      if(!p.last||!p.first){$('risSaveStatus').textContent='Confirm both last name and first name before saving.';return;}
      if(p.birth&&ageForDOB(p.birth)===''){$('risSaveStatus').textContent='Birthdate must not be in the future.';return;}
      const latest=readRIS(ORDERS_KEY,[]),index=latest.findIndex(o=>o.id===selectedPatientId);if(index<0){refreshRIS();return;}
      if(signature(latest[index])!==loadedSignature){$('risSaveStatus').textContent='Patient information changed in another RIS page. Reload the patient before saving your edits.';return;}
      const order=latest[index],e=extrasFor(order),name=[p.last,[p.first,p.middle].filter(Boolean).join(' ')].join(', ');
      const extra={...e,sex:p.sex==='male'?'Male':p.sex==='female'?'Female':'',dob:p.birth};
      latest[index]={...order,patientName:name,hospitalNo:p.record,age:p.age,ward:p.ward,kardexExtra:extra,patientHeading:{last:p.last,first:p.first,middle:p.middle,sourceName:name},updatedAt:new Date().toISOString()};
      const allExtra=readRIS(EXTRAS_KEY,{});allExtra[selectedPatientId]={...(allExtra[selectedPatientId]||{}),...extra};
      RISStore.setItem(EXTRAS_KEY,JSON.stringify(allExtra));RISStore.setItem(ORDERS_KEY,JSON.stringify(latest));
      dirtyPatient=false;risOrders=RISPatientOrder.sortByRoom(latest);loadedSignature=signature(latest[index]);updateRISPicker();$('risPatientSummary').textContent=`${name} · Room ${order.roomNumber||'—'} · HN ${p.record||'—'}`;$('risNameWarning').textContent='Saved name fields loaded.';$('risSaveStatus').textContent='Patient information saved to RIS. Cloud sync follows the RIS account status.';await RISStore.flush();
    }
    function initializeRISPatients(){
      refreshRIS();let requested=new URLSearchParams(location.search).get('patient');if(requested){loadRISPatient(requested);if(!selectedPatientId)$('risSaveStatus').textContent='Requested patient was not found. Select a saved patient.';}else loadRISPatient('');
      $('risPatientPick').addEventListener('change',e=>{if(allowPatientSwitch())loadRISPatient(e.target.value);else updateRISPicker()});
      $('risPatientSearch').addEventListener('input',updateRISPicker);
      for(let [id,step] of [['risPrev',-1],['risNext',1]])$(id).addEventListener('click',()=>{let items=filteredRIS(),i=items.findIndex(o=>o.id===selectedPatientId),next=items[i+step];if(next&&allowPatientSwitch())loadRISPatient(next.id)});
      $('risReload').addEventListener('click',()=>{if(allowPatientSwitch()){dirtyPatient=false;refreshRIS()}});$('risSave').addEventListener('click',saveRISPatient);
      for(let id of patientIds)$(id).addEventListener('input',()=>{dirtyPatient=Boolean(selectedPatientId);$('risSaveStatus').textContent=dirtyPatient?'Unsaved patient information changes.':'';updateBatchButtons();});
      document.querySelectorAll('input[name="sex"]').forEach(x=>x.addEventListener('change',()=>{dirtyPatient=Boolean(selectedPatientId);$('risSaveStatus').textContent=dirtyPatient?'Unsaved patient information changes.':'';updateBatchButtons();}));
      $('birth').addEventListener('input',()=>{$('age').value=ageForDOB($('birth').value);render()});
      window.addEventListener('storage',e=>{if([ORDERS_KEY,EXTRAS_KEY].includes(e.key))refreshRIS()});window.addEventListener('focus',refreshRIS);
      window.addEventListener('beforeunload',e=>{if(dirtyPatient||dirtyAlignments.size){e.preventDefault();e.returnValue=''}});
      window.addEventListener('ris-cloud-error',()=>{$('risSaveStatus').textContent='Saved locally; cloud sync failed. Check the RIS account status before leaving.';});
    }

    let printingBatch=false;
    const batchSelectedIds=new Set();
    function createPrintPage(v,patientId=''){
      const form=forms.find(f=>f.id===state.form),[w,h]=sizes[state.paper],s=settings();
      const page=document.createElement('div');page.className='heading-print-page';
      page.style.width=w+'mm';page.style.height=h+'mm';if(patientId)page.dataset.patientId=patientId;
      for(const [id] of fields){
        const txt=id==='male'?(v.sex==='male'?'X':''):id==='female'?(v.sex==='female'?'X':''):v[id]||'';
        if(!txt)continue;
        const pos=coordinates(id,form,s),out=document.createElement('span');
        out.className='print-field'+(id==='male'||id==='female'?' sex':'');out.textContent=txt;
        out.style.left=pos.x+'mm';out.style.top=pos.y+'mm';out.style.fontSize=s.font+'pt';page.append(out);
      }
      return page;
    }
    function valuesForRISOrder(order){
      const e=extrasFor(order),names=guessNames(order),birth=validDate(e.dob||order.birthdate||order.dob);
      return {last:names.last,first:names.first,middle:names.middle,record:String(order.hospitalNo||''),
        age:ageForDOB(birth)||String(order.age??''),birth:dateText(birth),sex:normalizedSex(e.sex||order.sex),ward:String(order.ward||'')};
    }
    function roomValue(order){return 'room:'+String(order.roomNumber||'').trim()}
    function batchPatients(){const room=$('batchRoom').value;return risOrders.filter(o=>room==='all'||roomValue(o)===room)}
    function clearBatchStatus(){$('batchStatus').textContent=''}
    function renderBatchPatients(){
      const roomPick=$('batchRoom'),previousRoom=roomPick.value||'all',rooms=[...new Set(risOrders.map(o=>String(o.roomNumber||'').trim()))];
      roomPick.replaceChildren();const all=document.createElement('option');all.value='all';all.textContent='All rooms';roomPick.append(all);
      for(const room of rooms){const option=document.createElement('option');option.value='room:'+room;option.textContent=room?'Room '+room:'No room assigned';roomPick.append(option)}
      if([...roomPick.options].some(o=>o.value===previousRoom))roomPick.value=previousRoom;
      else{roomPick.value='all';batchSelectedIds.clear()}
      const items=batchPatients(),visibleIds=new Set(items.map(o=>o.id));
      for(const id of batchSelectedIds)if(!visibleIds.has(id))batchSelectedIds.delete(id);
      const list=$('batchPatients');list.replaceChildren();
      if(!items.length){const empty=document.createElement('p');empty.className='muted batch-empty';empty.textContent='No saved patients in this room.';list.append(empty)}
      for(const order of items){
        const row=document.createElement('div');row.className='batch-patient-row';row.dataset.patientId=order.id;
        const label=document.createElement('label');label.className='batch-patient-label';
        const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=batchSelectedIds.has(order.id);checkbox.dataset.patientId=order.id;
        checkbox.setAttribute('aria-label','Select '+(order.patientName||'Unnamed patient')+' for heading printing');
        checkbox.addEventListener('change',()=>{if(checkbox.checked)batchSelectedIds.add(order.id);else batchSelectedIds.delete(order.id);clearBatchStatus();updateBatchButtons()});
        const details=document.createElement('span'),name=document.createElement('strong'),meta=document.createElement('small');
        name.textContent=order.patientName||'Unnamed patient';meta.textContent=`Room ${order.roomNumber||'—'} · HN ${order.hospitalNo||'—'}`;
        details.append(name,meta);const names=guessNames(order);
        if(!names.last||!names.first){const note=document.createElement('small');note.className='batch-needs-review';note.textContent='Confirm name fields before batch printing';details.append(note)}
        label.append(checkbox,details);
        const review=document.createElement('button');review.type='button';review.className='secondary batch-review';review.textContent='Review heading';
        review.addEventListener('click',()=>{if(allowPatientSwitch()){loadRISPatient(order.id);$('risPatientPick').scrollIntoView({behavior:'smooth',block:'center'})}});
        row.append(label,review);list.append(row);
      }
      updateBatchButtons();
    }
    function updateBatchButtons(){
      const items=batchPatients(),selected=items.filter(o=>batchSelectedIds.has(o.id)),test=$('testMode').checked,roomSelected=$('batchRoom').value!=='all';
      const dirtySelected=dirtyPatient&&selected.some(o=>o.id===selectedPatientId),dirtyRoom=dirtyPatient&&items.some(o=>o.id===selectedPatientId);
      $('printSelected').disabled=!selected.length||test||dirtySelected;
      $('printRoom').disabled=!roomSelected||!items.length||test||dirtyRoom;
      $('printSelected').textContent=selected.length?`Print selected headings (${selected.length})`:'Print selected headings';
      $('printRoom').textContent=roomSelected?`Print entire room (${items.length})`:'Print entire room';
      $('batchSelectAll').disabled=!items.length;$('batchSelectAll').checked=items.length>0&&selected.length===items.length;
      $('batchSelectAll').indeterminate=selected.length>0&&selected.length<items.length;
      $('batchSelectAllLabel').textContent=roomSelected?'Select all in this room':'Select all patients';$('batchClear').disabled=!selected.length;
      $('batchSelectionCount').textContent=`${selected.length} of ${items.length} patient(s) selected · ${selected.length} heading page(s).`+
        (test?' Turn off test print mode to print saved patients.':dirtySelected||roomSelected&&dirtyRoom?' Save or reload the current patient’s edits before including them in batch printing.':'');
      const form=forms.find(f=>f.id===state.form);$('batchTemplate').textContent=`${form.title} · ${form.code} · ${state.paper==='letter'?'US Letter':'A4'} · one sheet per patient`;
    }
    function printBatch(mode){
      clearBatchStatus();
      if($('testMode').checked){$('batchStatus').textContent='Turn off test print mode before printing saved patient headings.';return}
      const room=$('batchRoom').value,requestedIds=[...batchSelectedIds];
      if(mode==='room'&&room==='all'){$('batchStatus').textContent='Choose a room to print every patient in that room.';return}
      risOrders=RISPatientOrder.sortByRoom(readRIS(ORDERS_KEY,[]));
      const orders=risOrders.filter(o=>(room==='all'||roomValue(o)===room)&&(mode==='room'||requestedIds.includes(o.id)));
      renderBatchPatients();
      if(mode==='selected'&&orders.length!==requestedIds.length){$('batchStatus').textContent='Selected patients were removed or changed rooms. Review the current list and select them again.';return}
      if(!orders.length){$('batchStatus').textContent='Select at least one patient to print.';return}
      if(dirtyPatient&&orders.some(o=>o.id===selectedPatientId)){$('batchStatus').textContent='Save or reload the current patient’s edits before batch printing.';return}
      const invalid=orders.filter(o=>{const n=guessNames(o);return !n.last||!n.first});
      if(invalid.length){$('batchStatus').textContent='Confirm and save separate last and first name fields for: '+invalid.map(o=>o.patientName||o.hospitalNo||'Unnamed patient').join('; ')+'. Use Review heading beside each patient.';return}
      printingBatch=true;
      $('printSheet').replaceChildren(...orders.map(o=>createPrintPage(valuesForRISOrder(o),o.id)));
      $('batchStatus').textContent=`${orders.length} heading page(s) prepared in room order. Load ${orders.length} pre-printed sheet(s) of ${forms.find(f=>f.id===state.form).title}; set Copies to 1.`;
      try{window.print()}catch{printingBatch=false;render();$('batchStatus').textContent='The print dialog could not open. Please try again.'}
    }
    function initializeBatchPrinting(){
      $('batchRoom').addEventListener('change',()=>{batchSelectedIds.clear();clearBatchStatus();renderBatchPatients()});
      $('batchSelectAll').addEventListener('change',e=>{for(const order of batchPatients()){if(e.target.checked)batchSelectedIds.add(order.id);else batchSelectedIds.delete(order.id)}clearBatchStatus();renderBatchPatients()});
      $('batchClear').addEventListener('click',()=>{batchSelectedIds.clear();clearBatchStatus();renderBatchPatients()});
      $('printSelected').addEventListener('click',()=>printBatch('selected'));$('printRoom').addEventListener('click',()=>printBatch('room'));
      window.addEventListener('beforeprint',()=>{if(!printingBatch)render()});
      window.addEventListener('afterprint',()=>{printingBatch=false;render()});
      renderBatchPatients();
    }

    syncControls();render();
    initializeRISPatients();
    initializeBatchPrinting();
  })();
